// When (replaces switch — exhaustive when used as expression)
val result = when (x) {
    0 -> "zero"
    1, 2 -> "one or two"
    in 3..10 -> "small"
    is String -> "it's a string: $x"
    else -> "other"
}

// When without argument (replaces if-else chain)
when {
    x < 0 -> "negative"
    x == 0 -> "zero"
    else -> "positive"
}

